/* Nord Hub frontend. HubStore uses the API in connected mode and browser storage only in preview mode. */
const seed={
 projects:[
  {id:'p-hub',name:'Nord Hub',description:'Developer workspace para organizar e terminar projetos.',status:'Em Foco',priority:'Alta',progress:38,due:'2026-12-18',icon:'fa-compass'},
  {id:'p-inv',name:'Nord Inventory',description:'Inventário modular e estável para FiveM.',status:'Em Desenvolvimento',priority:'Alta',progress:72,due:'2026-11-03',icon:'fa-boxes-stacked'},
  {id:'p-saas',name:'Nord SaaS Lite',description:'Plataforma de serviços e comunidades Nord.',status:'Em Desenvolvimento',priority:'Média',progress:54,due:'2026-11-21',icon:'fa-cloud'},
  {id:'p-forge',name:'Nord Forge',description:'Ferramentas de desenvolvimento e distribuição.',status:'Em Espera',priority:'Média',progress:26,due:'2026-12-05',icon:'fa-hammer'},
  {id:'p-phone',name:'Nord Phone',description:'Sistema de telemóvel e aplicações para FiveM.',status:'Bloqueado',priority:'Baixa',progress:61,due:'2026-12-12',icon:'fa-mobile-screen-button'}
 ],
 tasks:[
  {id:'t-1',title:'Fechar fluxo de criação de projeto',projectId:'p-hub',status:'Em Curso',priority:'Alta',due:'Hoje',estimate:90,done:false},
  {id:'t-2',title:'Definir estados e filtros de tarefas',projectId:'p-hub',status:'Por Fazer',priority:'Média',due:'Hoje',estimate:45,done:false},
  {id:'t-3',title:'Rever dependências do sistema de notas',projectId:'p-hub',status:'Por Fazer',priority:'Baixa',due:'Amanhã',estimate:30,done:false},
  {id:'t-4',title:'Validar registo de itens na bridge',projectId:'p-inv',status:'Em Testes',priority:'Alta',due:'Hoje',estimate:60,done:false},
  {id:'t-5',title:'Preparar notas da próxima release',projectId:'p-saas',status:'Por Fazer',priority:'Média',due:'Sex, 17 Out',estimate:45,done:false},
  {id:'t-6',title:'Documentar recuperação de sessão',projectId:'p-hub',status:'Concluída',priority:'Baixa',due:'Ontem',estimate:25,done:true}
 ],
 ideas:[
  {id:'i-1',title:'Modo de revisão antes da release',description:'Lista guiada de testes e confirmações antes de publicar uma versão.',created:'Hoje'},
  {id:'i-2',title:'Resumo de desenvolvimento por projeto',description:'Gerar um resumo semanal a partir das notas e tarefas concluídas.',created:'Ontem'},
  {id:'i-3',title:'Etiquetas de contexto técnico',description:'Guardar framework, linguagem e serviços externos usados em cada projeto.',created:'12 Out'}
 ],
 notes:[
  {id:'n-1',projectId:'p-hub',title:'Ponto de retoma — Centro de Trabalho',body:'O fluxo principal deve mostrar primeiro o próximo passo. Continuar pelos formulários de projeto e tarefa; garantir que capturas urgentes preservam o contexto anterior.',updated:'Hoje, 09:42'},
  {id:'n-2',projectId:'p-inv',title:'Bridge Nord Inventory',body:'Rever o contrato de registo de itens e testar os handlers externos. Não assumir exports de auto-registo sem confirmar a documentação.',updated:'Ontem, 17:18'}
 ],
 notifications:[
  {id:'not-1',title:'Tarefa com prazo hoje',body:'Validar registo de itens na bridge · Nord Inventory',kind:'Prazo',time:'Há 18 min'},
  {id:'not-2',title:'Projeto bloqueado',body:'Nord Phone está marcado como bloqueado. Adiciona o motivo e o próximo passo.',kind:'Bloqueio',time:'Ontem'},
  {id:'not-3',title:'Semana por planear',body:'Tens 4,5 horas disponíveis por distribuir esta semana.',kind:'Planeamento',time:'12 Out'}
 ],
 releases:[{id:'r-1',projectId:'p-inv',version:'v2.0.0',title:'Nord Inventory 2.0',status:'Em preparação',date:'03 Nov 2026',tasks:8},{id:'r-2',projectId:'p-saas',version:'v0.9.2',title:'Nord SaaS Lite',status:'Planeada',date:'21 Nov 2026',tasks:5}],
 events:[{day:15,title:'Bloco de foco · Nord Hub',color:''},{day:15,title:'Bridge inventory',color:'blue'},{day:17,title:'Planeamento semanal',color:'orange'},{day:21,title:'Review Nord SaaS',color:'blue'},{day:28,title:'Fechar release',color:''}],
 preferences:{theme:'dark',language:'pt',availability:18}
};
let apiEnabled=false,apiUser=null,apiWorkspace=null;
const apiCollections={projects:'projects',tasks:'tasks',ideas:'ideas',notes:'notes',events:'events',releases:'releases',notifications:'notifications'};
const previewPreferences=()=>{try{return JSON.parse(localStorage.getItem('nordHub.preferences')||'{}')}catch{return {}}};
const HubStore={key:'nordHub.frontend.v1',load(){try{const saved=JSON.parse(localStorage.getItem(this.key)||'null');return saved?{...structuredClone(seed),...saved}:structuredClone(seed)}catch{return structuredClone(seed)}},save(){if(apiEnabled){localStorage.setItem('nordHub.preferences',JSON.stringify(state.preferences));return}localStorage.setItem(this.key,JSON.stringify(state))},add(collection,item){const record={id:crypto.randomUUID?.()||String(Date.now()),...item};state[collection].unshift(record);if(apiEnabled){window.nordHubApi.create(apiCollections[collection],item).then(remote=>{state[collection]=state[collection].map(x=>x.id===record.id?{...remote.payload,id:remote.id}:x);render()}).catch(err=>toast(`Não foi possível guardar: ${err.message}`,'fa-triangle-exclamation'))}else this.save();return record},update(collection,id,patch){state[collection]=state[collection].map(x=>x.id===id?{...x,...patch}:x);if(apiEnabled)window.nordHubApi.patch(apiCollections[collection],id,patch).catch(err=>toast(`Não foi possível atualizar: ${err.message}`,'fa-triangle-exclamation'));else this.save()},remove(collection,id){state[collection]=state[collection].filter(x=>x.id!==id);if(apiEnabled)window.nordHubApi.remove(apiCollections[collection],id).catch(err=>toast(`Não foi possível remover: ${err.message}`,'fa-triangle-exclamation'));else this.save()}};
let state=HubStore.load();state.preferences={...seed.preferences,...previewPreferences(),...state.preferences};
let currentPage='today',filterTask='Todas',calendarOffset=0,focusSeconds=25*60,focusInterval=null,adminTab='updates',captureType='Tarefa',isEmergency=false;
let gatewayData={status:null,maintenance:null,services:[],updates:[],history:[],loading:false};
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],content=$('#page-content');
const pageNames={today:'Centro de Trabalho',projects:'Projetos',tasks:'Tarefas',calendar:'Calendário',planner:'Planeador semanal',inbox:'Inbox de ideias',notes:'Notas e retoma',focus:'Modo Foco',releases:'Releases',team:'Equipa',notifications:'Notificações',gateway:'Gateway'};
const iconFor={Tarefa:'fa-list-check',Bug:'fa-bug',Nota:'fa-note-sticky',Lembrete:'fa-bell',Ideia:'fa-lightbulb'};
const projectName=id=>state.projects.find(p=>p.id===id)?.name||'Sem projeto';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const priorityClass=p=>p==='Alta'?'high':p==='Média'?'medium':'low';
function toast(message,icon='fa-circle-check'){const node=document.createElement('div');node.className='toast';node.innerHTML=`<i class="fa-solid ${icon}"></i><span>${safe(message)}</span>`;$('#toast-root').append(node);setTimeout(()=>node.remove(),3200)}
function goto(page){currentPage=page;$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#crumb').textContent=pageNames[page]||page;$('#sidebar').classList.remove('open');render();content.focus({preventScroll:true});if(page==='gateway'&&apiEnabled)loadGateway()}
function setCounts(){$('#project-count').textContent=state.projects.length;$('#idea-count').textContent=state.ideas.length}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">NORD HUB / ${safe(title)}</p><h1>${safe(title)}</h1><p>${safe(desc)}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(text,action,primary=false,icon=''){return `<button class="button ${primary?'primary':''}" data-action="${action}">${icon?`<i class="fa-solid ${icon}"></i>`:''}${safe(text)}</button>`}
function taskRows(tasks){if(!tasks.length)return `<div class="empty-state"><i class="fa-regular fa-circle-check"></i><h3>Sem tarefas por aqui</h3><p>Cria uma tarefa ou altera os filtros.</p><button class="button primary" data-action="new-task"><i class="fa-solid fa-plus"></i> Criar tarefa</button></div>`;return `<div class="task-list">${tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><input class="task-check" type="checkbox" data-complete="${t.id}" ${t.done?'checked':''} aria-label="Concluir ${safe(t.title)}"><div class="task-copy"><strong>${safe(t.title)}</strong><small>${safe(projectName(t.projectId))} · ${safe(t.due)}${t.estimate?` · ${t.estimate} min`:''}</small></div><span class="priority-pill ${priorityClass(t.priority)}">${safe(t.priority)}</span></div>`).join('')}</div>`}
function projectCards(projects=state.projects.slice(0,3)){if(!projects.length)return `<div class="empty-state"><i class="fa-solid fa-layer-group"></i><h3>Ainda sem projetos</h3><p>Cria um projeto para organizar o desenvolvimento.</p>${button('Criar primeiro projeto','new-project',true,'fa-plus')}</div>`;return `<div class="project-grid">${projects.map(p=>`<article class="project-card" data-project="${p.id}" tabindex="0"><div class="project-card-head"><span class="project-icon"><i class="fa-solid ${safe(p.icon||'fa-cube')}"></i></span><span class="status-pill ${p.status==='Em Espera'?'paused':p.status==='Bloqueado'?'blocked':p.status==='Concluído'?'done':''}">${safe(p.status)}</span></div><h3>${safe(p.name)}</h3><p>${safe(p.description)}</p><div class="project-progress"><i style="width:${Math.min(100,Number(p.progress)||0)}%"></i></div><div class="project-footer"><span>${p.progress}% concluído</span><span>${state.tasks.filter(t=>t.projectId===p.id&&!t.done).length} tarefas abertas</span></div></article>`).join('')}</div>`}
function dashboard(){const active=state.projects.find(p=>p.status==='Em Foco')||state.projects[0],today=state.tasks.filter(t=>!t.done&&t.due==='Hoje');return `${heading('Centro de Trabalho','O próximo passo do teu trabalho, num só lugar.',button('Nova tarefa','new-task',true,'fa-plus'))}<div class="grid dashboard-grid"><div><section class="panel focus-card"><div class="focus-top"><span class="focus-badge"><i class="fa-solid fa-circle"></i> PROJETO EM FOCO</span><button class="text-button" data-action="change-focus">Alterar projeto</button></div><h2>${safe(active?.name||'Escolhe um projeto')}</h2><p>${safe(active?.description||'Cria um projeto para começar.')}</p><div class="focus-meta"><span><i class="fa-regular fa-clock"></i> Próximo passo: ${safe(today[0]?.title||'Define uma tarefa para hoje')}</span><span><i class="fa-solid fa-chart-simple"></i> ${active?.progress||0}% concluído</span></div><div class="focus-footer"><button class="resume-button" data-goto="focus"><i class="fa-solid fa-play"></i> Retomar desenvolvimento</button><div class="avatar-stack"><span>R</span><small>Última sessão há 2 h</small></div></div></section><div class="stats-row"><div class="stat-card"><div class="stat-label"><i class="fa-solid fa-list-check"></i> Tarefas de hoje</div><div class="stat-value">${today.filter(t=>!t.done).length}<span style="font-size:12px;color:var(--muted);font-weight:500"> / ${today.length||2}</span></div><div class="stat-note good">${today.filter(t=>t.done).length?`${today.filter(t=>t.done).length} concluída(s)`: 'Um passo de cada vez'}</div></div><div class="stat-card"><div class="stat-label"><i class="fa-solid fa-layer-group"></i> Projetos ativos</div><div class="stat-value">${state.projects.filter(p=>!['Concluído','Arquivado'].includes(p.status)).length}</div><div class="stat-note">${state.projects.filter(p=>p.status==='Bloqueado').length} bloqueado(s)</div></div><div class="stat-card"><div class="stat-label"><i class="fa-regular fa-hourglass-half"></i> Tempo planeado</div><div class="stat-value">4,5<span style="font-size:12px"> h</span></div><div class="stat-note">de ${state.preferences.availability} h disponíveis</div></div></div><section class="panel today-panel section-spacer"><div class="panel-head"><div><h2>O que fazer hoje</h2><p>Prioridades para manter o ritmo.</p></div><button class="text-button" data-goto="tasks">Ver todas <i class="fa-solid fa-arrow-right"></i></button></div>${taskRows(today.slice(0,4))}</section></div><div class="side-stack"><section class="panel week-card"><div class="panel-head"><div><h2>Esta semana</h2><p>15 — 21 de outubro</p></div><button class="text-button" data-goto="planner">Planear</button></div><div class="week-days">${[['S',12],['T',13],['Q',14],['Q',15],['S',16],['S',17],['D',18]].map(([d,n])=>`<div class="week-day ${n===15?'today':''} ${[15,17].includes(n)?'has-work':''}">${d}<b>${n}</b></div>`).join('')}</div><div class="week-summary"><span>Tempo reservado</span><strong>4,5 h de 18 h</strong></div></section><section class="panel"><div class="panel-head"><div><h2>Último ponto de retoma</h2><p>Nord Hub · Hoje, 09:42</p></div><button class="text-button" data-goto="notes">Abrir</button></div><div class="resume-note"><div class="note-label"><i class="fa-solid fa-bookmark"></i> PONTO DE RETOMA</div><p>${safe(state.notes[0]?.body||'Guarda o teu próximo passo para retomares mais tarde.')}</p><small>Próximo passo · continuar pelos formulários</small></div></section><section class="panel"><div class="panel-head"><div><h2>Precisas de registar algo?</h2><p>Guarda sem perder o foco.</p></div></div><button class="button" data-action="quick-capture"><i class="fa-solid fa-bolt"></i> Captura rápida</button><button class="button" data-action="emergency" style="margin-left:6px"><i class="fa-solid fa-triangle-exclamation"></i> Emergência</button></section></div></div><section class="section-spacer"><div class="section-row"><h2>Projetos em andamento</h2><button class="text-button" data-goto="projects">Ver projetos <i class="fa-solid fa-arrow-right"></i></button></div>${projectCards()}</section>`}
function projectsPage(){const actions=`<button class="button" data-action="recommendations"><i class="fa-solid fa-wand-magic-sparkles"></i> Rever prioridades</button>${button('Novo projeto','new-project',true,'fa-plus')}`;return `${heading('Projetos','Mantém os objetivos e próximos passos visíveis.',actions)}<div class="filters"><select class="select-control" id="project-status-filter"><option value="Todos">Todos os estados</option>${['Em Foco','Em Desenvolvimento','Em Espera','Bloqueado','Concluído','Arquivado'].map(x=>`<option>${x}</option>`).join('')}</select><input class="filter-input" id="project-search" placeholder="Pesquisar projetos..."></div><div id="project-results">${projectCards(state.projects)}</div>`}
function tasksPage(){const list=state.tasks.filter(t=>filterTask==='Todas'||t.status===filterTask);return `${heading('Tarefas','Divide o trabalho em passos claros e executáveis.',button('Nova tarefa','new-task',true,'fa-plus'))}<div class="filters"><select class="select-control" id="task-filter">${['Todas','Por Fazer','Em Curso','Em Testes','Bloqueada','Concluída'].map(x=>`<option ${filterTask===x?'selected':''}>${x}</option>`).join('')}</select><select class="select-control" id="task-project"><option value="Todos">Todos os projetos</option>${state.projects.map(p=>`<option value="${p.id}">${safe(p.name)}</option>`).join('')}</select><span style="color:var(--muted);font-size:10px;margin-left:auto">${list.length} tarefa(s)</span></div><section class="panel">${taskRows(list)}</section>`}
function calendarPage(){const base=new Date(2026,9+calendarOffset,1),month=base.toLocaleDateString('pt-PT',{month:'long',year:'numeric'}),start=(base.getDay()+6)%7,days=new Date(base.getFullYear(),base.getMonth()+1,0).getDate(),prevDays=new Date(base.getFullYear(),base.getMonth(),0).getDate();let cells='';for(let i=0;i<42;i++){let n=i-start+1,muted=n<1||n>days,day=n<1?prevDays+n:n>days?n-days:n;let ev=state.events.filter(e=>e.day===day&&!muted);cells+=`<div class="calendar-cell"><span class="calendar-date ${muted?'muted':''} ${!muted&&day===15&&calendarOffset===0?'today':''}">${day}</span>${ev.map(e=>`<div class="calendar-event ${e.color}">${safe(e.title)}</div>`).join('')}</div>`}return `${heading('Calendário','Prazos e blocos de trabalho, no mesmo calendário.',button('Novo bloco','new-event',true,'fa-plus'))}<section class="panel calendar-panel"><div class="calendar-toolbar"><div class="calendar-month">${month[0].toUpperCase()+month.slice(1)}</div><div class="calendar-controls"><button data-action="calendar-prev" aria-label="Mês anterior"><i class="fa-solid fa-chevron-left"></i></button><button data-action="calendar-today">Hoje</button><button data-action="calendar-next" aria-label="Mês seguinte"><i class="fa-solid fa-chevron-right"></i></button></div></div><div class="calendar-grid">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div class="calendar-cell weekday">${x}</div>`).join('')}${cells}</div></section><div class="section-spacer" style="color:var(--muted);font-size:10px"><i class="fa-regular fa-circle-info"></i> A data-limite de uma tarefa é independente do tempo reservado para a executar.</div>`}
function plannerPage(){const days=[['Segunda','13 Out'],['Terça','14 Out'],['Quarta','15 Out'],['Quinta','16 Out'],['Sexta','17 Out']];let incomplete=state.tasks.filter(t=>!t.done);return `${heading('Planeador semanal','Distribui o trabalho de acordo com o tempo que tens disponível.',button('Ajustar disponibilidade','availability'))}<section class="panel" style="margin-bottom:14px"><div class="panel-head"><div><h2>Plano sugerido para esta semana</h2><p>Estimativas baseadas nas tarefas abertas. Revê antes de adicionar ao calendário.</p></div><span class="status-pill">${state.preferences.availability} h disponíveis</span></div><div style="display:flex;gap:10px;flex-wrap:wrap"><span class="priority-pill high">${incomplete.filter(t=>t.priority==='Alta').length} prioridades altas</span><span class="priority-pill medium">${incomplete.reduce((sum,t)=>sum+(Number(t.estimate)||0),0)} min estimados</span><button class="button small" data-action="accept-plan"><i class="fa-solid fa-calendar-plus"></i> Adicionar blocos ao calendário</button></div></section><div class="grid planner-grid">${days.map((d,i)=>{let daily=incomplete.filter((t,n)=>n%5===i).slice(0,3);return `<section class="planner-day"><h3>${d[0]}</h3><small>${d[1]} · ${daily.reduce((a,t)=>a+(Number(t.estimate)||0),0)} min</small>${daily.length?daily.map(t=>`<article class="plan-task"><b>${safe(t.title)}</b><span>${safe(projectName(t.projectId))} · ${t.estimate} min</span></article>`).join(''):'<small>Espaço livre para trabalho ou descanso.</small>'}</section>`}).join('')}</div><p style="font-size:9px;color:var(--muted);margin-top:12px">O planeamento usa regras simples e não altera datas sem a tua aprovação. Sugestões de IA poderão ser adicionadas como opção.</p>`}
function inboxPage(){let actions=`<button class="button" data-action="draw-idea"><i class="fa-solid fa-shuffle"></i> Sortear ideia</button>${button('Nova ideia','new-idea',true,'fa-plus')}`;return `${heading('Inbox de ideias','Guarda ideias para não interromper o projeto em que estás.',actions)}${state.ideas.length?state.ideas.map(i=>`<article class="idea-card"><div class="idea-icon"><i class="fa-regular fa-lightbulb"></i></div><div class="idea-body"><b>${safe(i.title)}</b><p>${safe(i.description)}</p><small>${safe(i.created)} · Ideia</small></div><div class="idea-actions"><button class="icon-action" data-convert-idea="${i.id}" title="Converter em tarefa"><i class="fa-solid fa-arrow-turn-down"></i></button><button class="icon-action" data-delete-idea="${i.id}" title="Arquivar"><i class="fa-solid fa-box-archive"></i></button></div></article>`).join(''):`<section class="panel">${empty('fa-lightbulb','A Inbox está vazia','Regista uma ideia agora e volta ao que estavas a fazer.',button('Registar ideia','new-idea',true,'fa-plus'))}</section>`}`}
function empty(icon,title,desc,cta=''){return `<div class="empty-state"><i class="fa-regular ${icon}"></i><h3>${title}</h3><p>${desc}</p>${cta}</div>`}
function notesPage(){return `${heading('Notas e retoma','Regista o contexto para continuares sem recomeçar do zero.',button('Novo ponto de retoma','new-note',true,'fa-plus'))}<div class="grid note-grid">${state.notes.map(n=>`<article class="note-card"><p class="eyebrow">${safe(projectName(n.projectId))}</p><h3>${safe(n.title)}</h3><p>${safe(n.body)}</p><small>Atualizado ${safe(n.updated)}</small><div style="margin-top:12px"><button class="button small" data-action="edit-note" data-id="${n.id}"><i class="fa-regular fa-pen-to-square"></i> Editar</button></div></article>`).join('')}</div>`}
function focusPage(){return `${heading('Modo Foco','Uma vista simples para a sessão de desenvolvimento.',button('Guardar ponto de retoma','new-note',false,'fa-bookmark'))}<div class="focus-mode"><section class="focus-surface"><p class="eyebrow">SESSÃO DE DESENVOLVIMENTO · ${safe(projectName(state.projects.find(p=>p.status==='Em Foco')?.id))}</p><div class="focus-title">${safe(state.tasks.find(t=>!t.done&&t.status==='Em Curso')?.title||'Escolhe o próximo passo')}</div><p style="font-size:11px;color:var(--muted);margin:0">Trabalha numa coisa de cada vez. Podes capturar uma nova ideia sem sair daqui.</p><div class="focus-timer" id="focus-timer">25:00</div><div class="focus-controls"><button class="button primary" id="timer-toggle"><i class="fa-solid fa-play"></i> Começar foco</button><button class="button" id="timer-reset"><i class="fa-solid fa-rotate-left"></i> Reiniciar</button></div><div class="focus-checklist"><div class="panel-head"><h2>Tarefas da sessão</h2><button class="text-button" data-action="quick-capture">Capturar</button></div>${taskRows(state.tasks.filter(t=>!t.done).slice(0,3))}</div></section></div>`}
function releasesPage(){return `${heading('Releases','Acompanha versões e o trabalho necessário até à publicação.',button('Nova release','new-release',true,'fa-plus'))}<section class="panel">${state.releases.map(r=>`<div class="release-row"><span class="release-mark"><i class="fa-solid fa-rocket"></i></span><div class="release-copy"><b>${safe(r.title)} <span style="color:var(--accent)">${safe(r.version)}</span></b><p>${safe(projectName(r.projectId))} · ${r.tasks} tarefas associadas</p></div><span class="status-pill ${r.status==='Planeada'?'paused':''}">${safe(r.status)}</span><span style="font-size:9px;color:var(--muted);min-width:90px;text-align:right">${safe(r.date)}</span></div>`).join('')}</section><p style="font-size:9px;color:var(--muted);margin-top:12px">Estas são releases dos teus projetos. As atualizações da plataforma estão no Gateway.</p>`}
function teamPage(){if(!apiEnabled)return `${heading('Equipa','Organiza responsabilidades dentro do teu espaço de trabalho.',button('Convidar pessoa','invite',true,'fa-user-plus'))}<section class="panel"><div class="panel-head"><div><h2>Nord-Lab</h2><p>Pré-visualização do espaço pessoal</p></div><span class="status-pill">Demo</span></div><div class="member-row"><span class="member-avatar">R</span><div class="member-copy"><b>Ricardo</b><div style="font-size:9px;color:var(--muted)">Administrador do espaço</div></div><span class="status-pill">Owner</span></div></section>`;const rows=(state.members||[]).map(m=>`<div class="member-row"><span class="member-avatar">${safe((m.displayName||m.email||'?').slice(0,1).toUpperCase())}</span><div class="member-copy"><b>${safe(m.displayName)}</b><div style="font-size:9px;color:var(--muted)">${safe(m.email)}${m.id===apiUser?.id?' · Tu':''}</div></div>${apiWorkspace?.role==='OWNER'&&m.role!=='OWNER'&&m.id!==apiUser?.id?`<select class="select-control" data-member-role="${m.id}" aria-label="Permissão de ${safe(m.displayName)}"><option ${m.role==='EDITOR'?'selected':''} value="EDITOR">Colaborador</option><option ${m.role==='VIEWER'?'selected':''} value="VIEWER">Leitura</option></select>`:`<span class="status-pill ${m.role==='VIEWER'?'done':''}">${m.role==='OWNER'?'Owner':m.role==='EDITOR'?'Colaborador':'Leitura'}</span>`}</div>`).join('');const inviteAction=apiWorkspace?.role==='OWNER'?button('Convidar pessoa','invite',true,'fa-user-plus'):'';return `${heading('Equipa','Membros e permissões deste espaço de trabalho.',inviteAction)}<section class="panel"><div class="panel-head"><div><h2>${safe(apiWorkspace?.name||'Espaço de trabalho')}</h2><p>${state.members?.length||0} membro(s) · permissões aplicadas no servidor</p></div><span class="status-pill">${safe(apiWorkspace?.role||'Membro')}</span></div>${rows||empty('fa-users','Sem membros','Não existem membros neste espaço.')}</section><p style="font-size:9px;color:var(--muted);margin-top:12px">Só o Owner pode alterar permissões. O servidor valida o acesso em cada pedido; esta interface não substitui as regras de segurança.</p>`}
function notificationsPage(){return `${heading('Notificações','Avisos úteis sem interromper o teu trabalho.',`<button class="button" data-action="mark-read"><i class="fa-solid fa-check-double"></i> Marcar como lidas</button>`)}<section class="panel">${state.notifications.length?state.notifications.map(n=>`<div class="notification-row"><span class="notification-icon"><i class="fa-regular fa-bell"></i></span><div class="notification-copy"><b>${safe(n.title)}</b><p>${safe(n.body)}</p></div><small style="font-size:9px;color:var(--muted)">${safe(n.time)}</small></div>`).join(''):empty('fa-bell','Tudo em dia','Não tens notificações pendentes.')}</section><p style="font-size:9px;color:var(--muted);margin-top:12px">Prazos, tarefas urgentes e bloqueios são agrupados para reduzir interrupções.</p>`}
function gatewayPage(){const tabs=[['updates','Atualizações','fa-rotate'],['maintenance','Manutenção','fa-screwdriver-wrench'],['services','Serviços','fa-heart-pulse'],['history','Histórico','fa-clock-rotate-left']];if(!apiEnabled){return `${heading('Gateway','Estado e administração da plataforma.','')}<div class="admin-tabs">${tabs.map(([id,label,icon])=>`<button class="admin-tab ${adminTab===id?'active':''}" data-admin-tab="${id}"><i class="fa-solid ${icon}"></i> ${label}</button>`).join('')}</div><section class="panel"><p style="font-size:10px;color:var(--muted)">Pré-visualização local. Liga o backend para consultar o estado real do Gateway.</p><span class="status-pill paused">Modo demo</span></section>`}let body='';if(gatewayData.loading)body='<div class="empty-state"><i class="fa-solid fa-spinner fa-spin"></i><h3>A consultar o Gateway</h3><p>A carregar estado atual do servidor.</p></div>';else if(adminTab==='updates'){const status=gatewayData.status;body=`<div class="panel-head"><div><h2>Estado da plataforma</h2><p>Nord Hub · API v1</p></div><span class="status-pill ${status?.state==='OPERATIONAL'?'':'paused'}">${safe(status?.state||'Desconhecido')} · ${safe(status?.version||'—')}</span></div><div class="release-row"><span class="release-mark"><i class="fa-solid fa-server"></i></span><div class="release-copy"><b>Modo de manutenção: ${safe(status?.maintenanceMode||'NORMAL')}</b><p>${safe(status?.message||'Sem aviso de manutenção.')}</p></div><small style="font-size:9px;color:var(--muted)">Verificado ${safe(status?.checkedAt||'')}</small></div><div class="panel-head section-spacer"><div><h2>Atualizações da plataforma</h2><p>Changelog publicado pelo administrador.</p></div>${apiUser?.globalAdmin?button('Publicar atualização','gateway-release',true,'fa-plus'):''}</div>${(gatewayData.updates||[]).map(r=>`<div class="release-row"><span class="release-mark"><i class="fa-solid fa-rotate"></i></span><div class="release-copy"><b>${safe(r.title)} <span style="color:var(--accent)">${safe(r.version)}</span></b><p>${safe(r.changelog)}</p></div><small style="font-size:9px;color:var(--muted)">${safe(r.publishedAt)}</small></div>`).join('')||empty('fa-circle-info','Sem atualizações publicadas','Quando houver uma nova versão, aparecerá aqui.')}`}else if(adminTab==='maintenance'){const m=gatewayData.maintenance;body=`<div class="panel-head"><div><h2>Modo de manutenção</h2><p>${safe(m?.message||'Sem intervenção agendada.')}</p></div><span class="status-pill ${m?.mode==='NORMAL'?'':'paused'}">${safe(m?.mode||'NORMAL')}</span></div><p style="font-size:10px;color:var(--muted)">Normal permite escrita; só leitura bloqueia alterações; total pausa as APIs até a manutenção ser alterada por um administrador.</p>${m?.startsAt?`<div class="release-row"><div class="release-copy"><b>Início</b><p>${safe(m.startsAt)}${m.endsAt?` · Fim ${safe(m.endsAt)}`:''}</p></div></div>`:''}${apiUser?.globalAdmin?button('Alterar manutenção','gateway-maintenance',true,'fa-screwdriver-wrench'):''}`}else if(adminTab==='services'){body=`<div class="panel-head"><div><h2>Estado dos serviços</h2><p>Verificação direta dos componentes ligados ao backend.</p></div></div>${(gatewayData.services||[]).map(s=>`<div class="member-row"><span class="status-light" style="background:${s.state==='OPERATIONAL'?'var(--green)':'var(--red)'}"></span><div class="member-copy"><b>${safe(s.name)}</b><div style="font-size:9px;color:var(--muted)">${safe(s.description)}</div></div><span class="status-pill ${s.state==='OPERATIONAL'?'':'blocked'}">${safe(s.state)}</span></div>`).join('')}`}else{body=apiUser?.globalAdmin?`${(gatewayData.history||[]).map(a=>`<div class="release-row"><span class="release-mark"><i class="fa-solid fa-shield-halved"></i></span><div class="release-copy"><b>${safe(a.action)}</b><p>${safe(JSON.stringify(a.details||{}))}</p></div><small style="font-size:9px;color:var(--muted)">${safe(a.createdAt)}</small></div>`).join('')||empty('fa-clock','Sem alterações registadas','Ações administrativas serão registadas aqui.')}`:empty('fa-lock','Acesso de administrador necessário','O histórico do Gateway só está disponível para administradores globais.')}return `${heading('Gateway','Estado e administração da plataforma.','')}<div class="admin-tabs">${tabs.map(([id,label,icon])=>`<button class="admin-tab ${adminTab===id?'active':''}" data-admin-tab="${id}"><i class="fa-solid ${icon}"></i> ${label}</button>`).join('')}</div><section class="panel">${body}</section>`}
function renderAuth(error=''){document.body.classList.add('auth-mode');content.innerHTML=`<div class="auth-screen"><section class="auth-card"><span class="brand-mark">N</span><p class="eyebrow">NORD HUB / CONTA</p><h1 id="auth-title">Entrar no Nord Hub</h1><p class="auth-description">Acede ao teu espaço de trabalho e continua de onde ficaste.</p>${error?`<div class="auth-error" role="alert">${safe(error)}</div>`:''}<form id="auth-form" data-mode="login"><div class="field" data-auth-register hidden><label for="auth-name">O teu nome</label><input id="auth-name" name="displayName" maxlength="80" autocomplete="name"></div><div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><div class="field"><label for="auth-password">Palavra-passe</label><input id="auth-password" name="password" type="password" required minlength="12" maxlength="100" autocomplete="current-password"></div><div class="field" data-auth-register hidden><label for="auth-workspace">Nome do espaço de trabalho</label><input id="auth-workspace" name="workspaceName" maxlength="80" placeholder="Ex.: Nord-Lab"></div><button class="button primary auth-submit" type="submit">Entrar</button></form><p class="auth-switch"><span id="auth-switch-text">Ainda não tens conta?</span> <button class="text-button" data-auth-mode="register">Criar conta</button></p><small>Ligação protegida. A palavra-passe é guardada com hash no servidor.</small></section></div>`}
function apiRows(rows){return rows.map(row=>({...row.payload,id:row.id,createdAt:row.createdAt,updatedAt:row.updatedAt}))}
async function hydrateApiSession(){const me=await window.nordHubApi.me();apiUser=me.user;const workspace=me.workspaces.find(w=>w.id===window.nordHubApi.workspaceId)||me.workspaces[0];if(!workspace)throw new Error('Esta conta ainda não tem um espaço de trabalho.');apiWorkspace=workspace;window.nordHubApi.workspaceId=workspace.id;sessionStorage.setItem('nordHub.workspaceId',workspace.id);const names=Object.keys(apiCollections);const loadedData=await Promise.all(names.map(name=>window.nordHubApi.list(apiCollections[name])));const loaded={};names.forEach((name,index)=>loaded[name]=apiRows(loadedData[index]));loaded.members=await window.nordHubApi.members();state={...state,...loaded,preferences:{...seed.preferences,...previewPreferences()}};currentPage='today';}
async function loadGateway(){gatewayData.loading=true;if(currentPage==='gateway')render();try{const jobs=[window.nordHubApi.gateway('status'),window.nordHubApi.gateway('maintenance'),window.nordHubApi.gateway('services'),window.nordHubApi.gateway('updates')];if(apiUser?.globalAdmin)jobs.push(window.nordHubApi.gateway('history'));const result=await Promise.all(jobs);gatewayData={status:result[0],maintenance:result[1],services:result[2],updates:result[3],history:apiUser?.globalAdmin?result[4]:[],loading:false};}catch(error){gatewayData.loading=false;toast(`Não foi possível obter o estado do Gateway: ${error.message}`,'fa-triangle-exclamation')}if(currentPage==='gateway')render()}
async function startApp(){try{apiEnabled=await window.nordHubApi.discover();if(apiEnabled){if(window.nordHubApi.token){try{await hydrateApiSession()}catch{window.nordHubApi.logout();apiUser=null}}render();return}}catch{}render()}
function render(){if(apiEnabled&&!window.nordHubApi.token){renderAuth();return}document.body.classList.remove('auth-mode');setCounts();if(apiUser){$('.profile-button b').textContent=apiUser.displayName;$('.profile-button small').textContent=apiUser.globalAdmin?'Administrador':'Membro'}const views={today:dashboard,projects:projectsPage,tasks:tasksPage,calendar:calendarPage,planner:plannerPage,inbox:inboxPage,notes:notesPage,focus:focusPage,releases:releasesPage,team:teamPage,notifications:notificationsPage,gateway:gatewayPage};content.innerHTML=(views[currentPage]||dashboard)();}
function switchAuthMode(mode){const registering=mode==='register',form=$('#auth-form');if(!form)return;form.dataset.mode=registering?'register':'login';$$('[data-auth-register]').forEach(n=>n.hidden=!registering);$('#auth-name').required=registering;$('#auth-title').textContent=registering?'Criar conta':'Entrar no Nord Hub';$('#auth-password').autocomplete=registering?'new-password':'current-password';$('.auth-submit').textContent=registering?'Criar conta':'Entrar';$('#auth-switch-text').textContent=registering?'Já tens conta?':'Ainda não tens conta?';$('[data-auth-mode]').textContent=registering?'Entrar':'Criar conta';$('[data-auth-mode]').dataset.authMode=registering?'login':'register';}
async function submitAuth(form){const data=formData(form),mode=form.dataset.mode;const payload=mode==='register'?{email:data.email,password:data.password,displayName:data.displayName,workspaceName:data.workspaceName}:{email:data.email,password:data.password};try{const session=mode==='register'?await window.nordHubApi.register(payload):await window.nordHubApi.login(payload);apiUser=session.user;const invite=new URLSearchParams(location.search).get('invite');if(invite){await window.nordHubApi.acceptInvite(invite);history.replaceState({},'',location.pathname);toast('Convite aceite')}await hydrateApiSession();render();if(!invite)toast(mode==='register'?'Conta criada com sucesso':'Sessão iniciada');}catch(error){renderAuth(error.message);if(mode==='register')switchAuthMode('register')}}
function modal(title,desc,body,submitText='Guardar'){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><form class="modal" id="active-form"><div class="modal-head"><div><h2>${safe(title)}</h2><p>${safe(desc)}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Fechar"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button primary" type="submit">${safe(submitText)}</button></div></form></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()})}
function closeModal(){$('#modal-root').innerHTML=''}
function projectSelect(value=''){return `<select name="projectId" required><option value="">Seleciona um projeto</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${safe(p.name)}</option>`).join('')}</select>`}
function newTask(prefill={}){modal('Criar tarefa','Define um próximo passo que consigas executar.',`<div class="form-grid"><div class="field full"><label for="task-title">O que precisa de ser feito?</label><input id="task-title" name="title" required maxlength="120" value="${safe(prefill.title||'')}" placeholder="Ex.: Rever o fluxo de autenticação"></div><div class="field"><label>Projeto</label>${projectSelect(prefill.projectId||'')}</div><div class="field"><label>Prioridade</label><select name="priority"><option>Alta</option><option selected>Média</option><option>Baixa</option></select></div><div class="field"><label>Estado</label><select name="status"><option>Por Fazer</option><option>Em Curso</option><option>Em Testes</option><option>Bloqueada</option></select></div><div class="field"><label>Prazo</label><select name="due"><option>Hoje</option><option>Amanhã</option><option>Esta semana</option><option>Sem prazo</option></select></div><div class="field"><label>Estimativa (minutos)</label><input type="number" min="5" step="5" name="estimate" value="30"></div></div>`)}
function newProject(){modal('Criar projeto','Começa com o objetivo e o próximo passo.',`<div class="form-grid"><div class="field full"><label>Nome do projeto</label><input name="name" required maxlength="70" placeholder="Ex.: Nord Hub"></div><div class="field full"><label>Objetivo</label><textarea name="description" maxlength="240" placeholder="O que queres concluir com este projeto?"></textarea></div><div class="field"><label>Estado</label><select name="status"><option>Em Desenvolvimento</option><option>Em Foco</option><option>Em Espera</option><option>Bloqueado</option></select></div><div class="field"><label>Prioridade</label><select name="priority"><option>Alta</option><option selected>Média</option><option>Baixa</option></select></div><div class="field"><label>Data alvo</label><input type="date" name="due"></div><div class="field"><label>Projeto principal</label><select name="focus"><option value="no">Não</option><option value="yes">Sim, colocar em foco</option></select></div></div>`)}
function newIdea(){modal('Guardar uma ideia','Regista agora e decide quando lhe vais dar prioridade.',`<div class="field"><label>Nome da ideia</label><input name="title" required maxlength="100" placeholder="Uma ideia para mais tarde"></div><div class="field"><label>Contexto</label><textarea name="description" maxlength="300" placeholder="O que queres explorar?"></textarea></div>`)}
function newNote(existing){const n=existing||{};modal(existing?'Editar ponto de retoma':'Novo ponto de retoma','Guarda o contexto e escreve o próximo passo com clareza.',`<div class="field"><label>Projeto</label>${projectSelect(n.projectId||'')}</div><div class="field"><label>Título</label><input name="title" required value="${safe(n.title||'')}" placeholder="Ex.: Onde fiquei"></div><div class="field"><label>O que fizeste e o que falta?</label><textarea name="body" required placeholder="Resumo, bloqueios e próximo passo">${safe(n.body||'')}</textarea></div>`,existing?'Guardar alterações':'Guardar ponto')}
function openCapture(emergency=false){captureType='Tarefa';isEmergency=emergency;modal(emergency?'Registar emergência':'Captura rápida',emergency?'Guarda o contexto atual e cria uma prioridade urgente.':'Regista algo sem perder o foco do projeto atual.',`<div class="capture-types">${[['Tarefa','fa-list-check'],['Bug','fa-bug'],['Nota','fa-note-sticky'],['Lembrete','fa-bell'],['Ideia','fa-lightbulb']].map(([n,i])=>`<button type="button" class="capture-type ${captureType===n?'active':''}" data-capture-type="${n}"><i class="fa-solid ${i}"></i>${n}</button>`).join('')}</div><div class="field"><label>Título</label><input name="title" required placeholder="O que queres guardar?"></div><div class="field"><label>Detalhes ou contexto atual</label><textarea name="description" placeholder="Adiciona um detalhe útil para retomares mais tarde"></textarea></div><div class="field"><label>Projeto</label>${projectSelect(state.projects.find(p=>p.status==='Em Foco')?.id||'')}</div>${emergency?'<div class="emergency-box"><i class="fa-solid fa-triangle-exclamation"></i> A tarefa ficará com prioridade alta. O teu ponto de retoma atual será preservado.</div>':''}`,'Registar')}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function handleSubmit(e){if(e.target.id==='auth-form'){e.preventDefault();submitAuth(e.target);return}if(e.target.id!=='active-form')return;e.preventDefault();const d=formData(e.target);if(currentPage==='projects'&&e.submitter?.dataset?.form==='edit')return;const title=d.title?.trim();if(e.target.dataset.kind==='task'){if(!title)return;HubStore.add('tasks',{title,projectId:d.projectId,status:d.status||'Por Fazer',priority:isEmergency?'Alta':d.priority||'Média',due:d.due||'Sem prazo',estimate:Number(d.estimate)||30,done:false});if(isEmergency&&d.projectId){const active=state.projects.find(p=>p.status==='Em Foco');if(active)HubStore.update('projects',active.id,{status:'Em Espera'})}toast(isEmergency?'Emergência guardada. Podes regressar ao ponto de retoma.':'Tarefa criada');closeModal();render();return}
 const kind=e.target.dataset.kind;
 if(kind==='project'){if(d.focus==='yes')state.projects.filter(p=>p.status==='Em Foco').forEach(p=>HubStore.update('projects',p.id,{status:'Em Desenvolvimento'}));HubStore.add('projects',{name:d.name.trim(),description:d.description.trim(),status:d.focus==='yes'?'Em Foco':d.status,priority:d.priority,progress:0,due:d.due||'',icon:'fa-cube'});HubStore.save();toast('Projeto criado');closeModal();render();return}
 if(kind==='idea'){HubStore.add('ideas',{title:d.title.trim(),description:d.description.trim(),created:'Agora'});toast('Ideia guardada na Inbox');closeModal();render();return}
 if(kind==='note'){if(e.target.dataset.id)HubStore.update('notes',e.target.dataset.id,{projectId:d.projectId,title:d.title.trim(),body:d.body.trim(),updated:'Agora'});else HubStore.add('notes',{projectId:d.projectId,title:d.title.trim(),body:d.body.trim(),updated:'Agora'});toast('Ponto de retoma guardado');closeModal();render();return}
 if(kind==='capture'){if(captureType==='Ideia'){HubStore.add('ideas',{title,description:d.description.trim(),created:'Agora'});toast('Ideia guardada na Inbox')}else if(captureType==='Nota'){HubStore.add('notes',{projectId:d.projectId,title,body:d.description.trim(),updated:'Agora'});toast('Nota guardada')}else{HubStore.add('tasks',{title,projectId:d.projectId,status:'Por Fazer',priority:isEmergency?'Alta':'Média',due:isEmergency?'Hoje':'Sem prazo',estimate:30,done:false});toast(isEmergency?'Emergência guardada':'Captura registada')}closeModal();render();return}
 if(kind==='event'){const day=Number(d.day)||15;HubStore.add('events',{day,title:d.title,color:d.kind==='Bloco de trabalho'?'blue':''});toast('Evento adicionado ao calendário');closeModal();render();return}
 if(kind==='release'){HubStore.add('releases',{projectId:d.projectId,version:d.version,title:d.title,status:'Planeada',date:d.date||'Data por definir',tasks:0});toast('Release planeada');closeModal();render();return}
 if(kind==='gatewayMaintenance'){if(!apiUser?.globalAdmin){toast('Apenas administradores globais podem alterar a manutenção','fa-lock');closeModal();return}const toIso=value=>value?new Date(value).toISOString():null;window.nordHubApi.gateway('maintenance',{method:'PUT',body:{mode:d.mode,message:d.message||null,startsAt:toIso(d.startsAt),endsAt:toIso(d.endsAt)}}).then(()=>{toast('Modo de manutenção atualizado');closeModal();loadGateway()}).catch(error=>toast(`Não foi possível atualizar: ${error.message}`,'fa-triangle-exclamation'));return}
 if(kind==='gatewayRelease'){if(!apiUser?.globalAdmin){toast('Apenas administradores globais podem publicar atualizações','fa-lock');closeModal();return}window.nordHubApi.gateway('updates',{method:'POST',body:{version:d.version,title:d.title,changelog:d.changelog}}).then(()=>{toast('Atualização publicada');closeModal();loadGateway()}).catch(error=>toast(`Não foi possível publicar: ${error.message}`,'fa-triangle-exclamation'));return}
 if(kind==='invite'){if(!apiEnabled){toast('Os convites reais ficam disponíveis quando o backend estiver ligado.','fa-circle-info');closeModal();return}window.nordHubApi.createInvite(d.email,d.role).then(result=>{const link=`${location.origin}${location.pathname}?invite=${encodeURIComponent(result.token)}`;modal('Convite criado','Copia este link e envia-o à pessoa indicada. Só pode ser utilizado uma vez e expira em 7 dias.',`<div class=\"field\"><label>Link de convite</label><input id=\"invite-link\" readonly value=\"${safe(link)}\"></div><p style=\"font-size:9px;color:var(--muted)\">O token só é mostrado agora. O email autorizado é ${safe(result.email)}.</p><button type=\"button\" class=\"button primary\" data-action=\"copy-invite\"><i class=\"fa-regular fa-copy\"></i> Copiar link</button>`,'Fechar');const submit=$('#active-form button[type=submit]');submit.type='button';submit.dataset.action='close-modal';submit.innerHTML='Fechar';}).catch(error=>toast(`Não foi possível criar o convite: ${error.message}`,'fa-triangle-exclamation'));return}
 if(kind==='availability'){state.preferences.availability=Number(d.hours)||18;HubStore.save();toast('Disponibilidade atualizada');closeModal();render();return}
}
function showForm(kind){if(kind==='new-task')newTask();else if(kind==='new-project')newProject();else if(kind==='new-idea')newIdea();else if(kind==='new-note')newNote();else if(kind==='new-event')modal('Adicionar ao calendário','Reserva tempo ou regista uma data importante.',`<div class="form-grid"><div class="field full"><label>Título</label><input name="title" required placeholder="Ex.: Bloco de desenvolvimento"></div><div class="field"><label>Dia do mês (outubro)</label><input type="number" name="day" min="1" max="31" value="15"></div><div class="field"><label>Tipo</label><select name="kind"><option>Bloco de trabalho</option><option>Evento</option><option>Lembrete</option></select></div><div class="field full"><label>Projeto (opcional)</label><select name="projectId"><option value="">Sem projeto associado</option>${state.projects.map(p=>`<option value="${p.id}">${safe(p.name)}</option>`).join('')}</select></div></div>`);else if(kind==='new-release')modal('Planear release','Define a versão e associa-a a um projeto.',`<div class="form-grid"><div class="field"><label>Projeto</label>${projectSelect()}</div><div class="field"><label>Versão</label><input name="version" required placeholder="v1.0.0"></div><div class="field full"><label>Nome da release</label><input name="title" required placeholder="Release de novembro"></div><div class="field"><label>Data alvo</label><input name="date" type="date"></div></div>`);else if(kind==='invite')modal('Convidar pessoa','Cria um link de utilização única, válido durante sete dias. A pessoa tem de criar uma conta com este email.',`<div class="field"><label>Email</label><input type="email" name="email" required maxlength="254" placeholder="colega@exemplo.com"></div><div class="field"><label>Permissão</label><select name="role"><option value="EDITOR">Colaborador</option><option value="VIEWER">Leitura</option></select></div>`,'Criar link de convite');else if(kind==='availability')modal('Disponibilidade semanal','Usa as horas reais que tens esta semana.',`<div class="field"><label>Horas de desenvolvimento</label><input type="number" min="1" max="80" name="hours" value="${state.preferences.availability}"></div>`)}
function openGatewayMaintenance(){const current=gatewayData.maintenance||{};modal('Alterar manutenção','A alteração é aplicada pelo Gateway e registada na auditoria.',`<div class="field"><label>Modo</label><select name="mode"><option value="NORMAL" ${current.mode==='NORMAL'?'selected':''}>Normal — leitura e escrita</option><option value="READ_ONLY" ${current.mode==='READ_ONLY'?'selected':''}>Só leitura — bloqueia alterações</option><option value="FULL" ${current.mode==='FULL'?'selected':''}>Total — pausa APIs</option></select></div><div class="field"><label>Aviso para utilizadores</label><textarea name="message" maxlength="500" placeholder="Opcional">${safe(current.message||'')}</textarea></div><div class="form-grid"><div class="field"><label>Início (opcional)</label><input type="datetime-local" name="startsAt"></div><div class="field"><label>Fim (opcional)</label><input type="datetime-local" name="endsAt"></div></div>`,'Aplicar modo')}
function openGatewayRelease(){if(!apiUser?.globalAdmin){toast('Apenas administradores globais podem publicar atualizações','fa-lock');return}modal('Publicar atualização','Regista a versão da plataforma e o respetivo changelog.',`<div class="form-grid"><div class="field"><label>Versão</label><input name="version" required maxlength="40" placeholder="v0.2.0"></div><div class="field"><label>Título</label><input name="title" required maxlength="120" placeholder="Nova versão do Nord Hub"></div><div class="field full"><label>Changelog</label><textarea name="changelog" required maxlength="10000" placeholder="Lista as alterações desta versão"></textarea></div></div>`,'Publicar')}
function action(name,el){if(name==='gateway-maintenance'){openGatewayMaintenance();return}if(name==='gateway-release'){openGatewayRelease();return}if(name==='copy-invite'){const input=$('#invite-link');input?.select();(navigator.clipboard?navigator.clipboard.writeText(input?.value||''):Promise.reject()).then(()=>toast('Link copiado')).catch(()=>toast('Seleciona e copia o link manualmente','fa-circle-info'));return}if(name==='new-task'||name==='new-project'||name==='new-idea'||name==='new-note'||name==='new-event'||name==='new-release'||name==='invite'||name==='availability'){showForm(name);return}if(name==='quick-capture'){openCapture(false);return}if(name==='emergency'){openCapture(true);return}if(name==='close-modal'){closeModal();return}if(name==='change-focus'){const next=state.projects.find(p=>p.status!=='Em Foco'&&p.status!=='Concluído');if(!next){toast('Cria um projeto primeiro','fa-circle-info');return}state.projects.filter(p=>p.status==='Em Foco').forEach(p=>HubStore.update('projects',p.id,{status:'Em Desenvolvimento'}));HubStore.update('projects',next.id,{status:'Em Foco'});render();toast(`${next.name} está agora em foco`);return}if(name==='recommendations'){const open=state.projects.filter(p=>!['Concluído','Arquivado'].includes(p.status));toast(open.length>4?`Tens ${open.length} projetos ativos. Considera escolher um foco principal.`:'As tuas prioridades estão equilibradas.');return}if(name==='calendar-prev'){calendarOffset--;render();return}if(name==='calendar-next'){calendarOffset++;render();return}if(name==='calendar-today'){calendarOffset=0;render();return}if(name==='draw-idea'){const i=state.ideas[Math.floor(Math.random()*state.ideas.length)];toast(i?`Ideia sorteada: ${i.title}`:'A Inbox está vazia','fa-shuffle');return}if(name==='accept-plan'){state.tasks.filter(t=>!t.done).slice(0,5).forEach((t,i)=>HubStore.add('events',{day:15+i,title:t.title,color:i%2?'blue':''}));toast('Blocos adicionados ao calendário');return}if(name==='mark-read'){if(apiEnabled){state.notifications.slice().forEach(n=>HubStore.remove('notifications',n.id))}else{state.notifications=[];HubStore.save()}render();toast('Notificações marcadas como lidas');return}if(name==='edit-note'){newNote(state.notes.find(n=>n.id===el.dataset.id));$('#active-form').dataset.kind='note';$('#active-form').dataset.id=el.dataset.id;return}if(name==='logout'){window.nordHubApi.logout();apiUser=null;apiWorkspace=null;state=HubStore.load();render();return}}
document.addEventListener('click',e=>{const authMode=e.target.closest('[data-auth-mode]');if(authMode){switchAuthMode(authMode.dataset.authMode);return}const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();goto(nav.dataset.page);return}const g=e.target.closest('[data-goto]');if(g){goto(g.dataset.goto);return}const b=e.target.closest('[data-action]');if(b){action(b.dataset.action,b);return}const tab=e.target.closest('[data-admin-tab]');if(tab){adminTab=tab.dataset.adminTab;render();if(apiEnabled)loadGateway();return}const type=e.target.closest('[data-capture-type]');if(type){captureType=type.dataset.captureType;$$('.capture-type').forEach(x=>x.classList.toggle('active',x===type));return}const idea=e.target.closest('[data-delete-idea]');if(idea){HubStore.remove('ideas',idea.dataset.deleteIdea);render();toast('Ideia arquivada');return}const convert=e.target.closest('[data-convert-idea]');if(convert){const i=state.ideas.find(x=>x.id===convert.dataset.convertIdea);if(i){closeModal();newTask({title:i.title});$('#active-form').dataset.kind='task';}return}const card=e.target.closest('[data-project]');if(card&&!e.target.closest('button')){const project=state.projects.find(p=>p.id===card.dataset.project);if(project){goto('tasks');$('#task-project').value=project.id;$('#task-project').dispatchEvent(new Event('change'))}return}if(e.target.closest('#quick-capture'))openCapture();if(e.target.id==='theme-toggle'||e.target.closest('#theme-toggle')){document.body.classList.toggle('light');state.preferences.theme=document.body.classList.contains('light')?'light':'dark';HubStore.save();$('#theme-toggle i').className=state.preferences.theme==='light'?'fa-regular fa-sun':'fa-regular fa-moon'}if(e.target.id==='mobile-menu'||e.target.closest('#mobile-menu'))$('#sidebar').classList.toggle('open');if(e.target.closest('#language-toggle'))action('toggle-language')});
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',e=>{if(e.target.matches('[data-complete]')){const task=state.tasks.find(t=>t.id===e.target.dataset.complete);if(task){HubStore.update('tasks',task.id,{done:e.target.checked,status:e.target.checked?'Concluída':'Por Fazer'});render();toast(e.target.checked?'Tarefa concluída':'Tarefa reaberta')}}if(e.target.id==='task-filter'){filterTask=e.target.value;render()}if(e.target.id==='task-project'){const id=e.target.value;$$('.task-row',content).forEach(row=>{const task=state.tasks.find(t=>t.id===row.querySelector('[data-complete]')?.dataset.complete);row.hidden=!!id&&id!=='Todos'&&task?.projectId!==id})}if(e.target.id==='project-status-filter'||e.target.id==='project-search')filterProjects()});
document.addEventListener('change',e=>{if(!e.target.matches('[data-member-role]'))return;const select=e.target;window.nordHubApi.changeMemberRole(select.dataset.memberRole,select.value).then(async()=>{state.members=await window.nordHubApi.members();render();toast('Permissão atualizada')}).catch(error=>{toast(`Não foi possível atualizar a permissão: ${error.message}`,'fa-triangle-exclamation');render()})});
document.addEventListener('input',e=>{if(e.target.id==='project-search')filterProjects();if(e.target.id==='global-search'){const q=e.target.value.trim().toLowerCase();if(q.length>1){const p=state.projects.find(x=>x.name.toLowerCase().includes(q));const t=state.tasks.find(x=>x.title.toLowerCase().includes(q));if(p){goto('projects');$('#project-search').value=q;filterProjects()}else if(t){goto('tasks');$('#task-filter').value='Todas';filterTask='Todas';render()}}}});
function filterProjects(){const status=$('#project-status-filter')?.value||'Todos',q=($('#project-search')?.value||'').toLowerCase();const results=state.projects.filter(p=>(status==='Todos'||p.status===status)&&(!q||p.name.toLowerCase().includes(q)||p.description.toLowerCase().includes(q)));const holder=$('#project-results');if(holder)holder.innerHTML=projectCards(results)}
function timerTick(){focusSeconds=Math.max(0,focusSeconds-1);const node=$('#focus-timer');if(node)node.textContent=`${String(Math.floor(focusSeconds/60)).padStart(2,'0')}:${String(focusSeconds%60).padStart(2,'0')}`;if(focusSeconds===0){clearInterval(focusInterval);focusInterval=null;toast('Sessão de foco concluída');}}
document.addEventListener('click',e=>{if(e.target.closest('#timer-toggle')){if(focusInterval){clearInterval(focusInterval);focusInterval=null;e.target.closest('#timer-toggle').innerHTML='<i class="fa-solid fa-play"></i> Continuar foco'}else{focusInterval=setInterval(timerTick,1000);e.target.closest('#timer-toggle').innerHTML='<i class="fa-solid fa-pause"></i> Pausar foco'}}if(e.target.closest('#timer-reset')){clearInterval(focusInterval);focusInterval=null;focusSeconds=25*60;const n=$('#focus-timer');if(n)n.textContent='25:00';const t=$('#timer-toggle');if(t)t.innerHTML='<i class="fa-solid fa-play"></i> Começar foco'}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus()}if(e.key.toLowerCase()==='q'&&!(apiEnabled&&!window.nordHubApi.token)&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){openCapture()}if(e.key==='Escape')closeModal()});
function setupFormKind(){const f=$('#active-form');if(!f)return;const modalTitle=$('.modal-head h2',f)?.textContent||'';if(modalTitle==='Criar tarefa')f.dataset.kind='task';else if(modalTitle==='Criar projeto')f.dataset.kind='project';else if(modalTitle==='Guardar uma ideia')f.dataset.kind='idea';else if(modalTitle==='Novo ponto de retoma'||modalTitle==='Editar ponto de retoma')f.dataset.kind='note';else if(modalTitle==='Captura rápida'||modalTitle==='Registar emergência')f.dataset.kind='capture';else if(modalTitle==='Adicionar ao calendário')f.dataset.kind='event';else if(modalTitle==='Planear release')f.dataset.kind='release';else if(modalTitle==='Convidar pessoa')f.dataset.kind='invite';else if(modalTitle==='Disponibilidade semanal')f.dataset.kind='availability';else if(modalTitle==='Alterar manutenção')f.dataset.kind='gatewayMaintenance';else if(modalTitle==='Publicar atualização')f.dataset.kind='gatewayRelease'}
const observer=new MutationObserver(()=>setupFormKind());observer.observe($('#modal-root'),{childList:true,subtree:true});
if(state.preferences.theme==='light')document.body.classList.add('light');
startApp();
